import{_ as a}from"./chunks/architecture_ascendc.DskTM2S5.js";import{_ as e,o as t,a as l,b as r}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"C++类库API","link":"/guide/programming_guide/library_api/library_api"},{"text":"编程接口概述","link":"/guide/programming_guide/library_api/programming_interface_overview"}]},"headers":[],"relativePath":"guide/programming_guide/library_api/programming_interface_overview.md","filePath":"guide/programming_guide/library_api/programming_interface_overview.md","lastUpdated":1787620066000}'),o={name:"guide/programming_guide/library_api/programming_interface_overview.md"};function c(n,i,s,d,_,p){return t(),l("div",null,[...i[0]||(i[0]=[r('<div><article class="markdown-body"><h1>编程接口概述<span id="ZH-CN_TOPIC_0000001976190182"></span></h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本章提供编程API的概述。具体API参考见<a href="../../../api/api_list.html">Ascend C API</a>。</p></div><p>Ascend C提供一组类库API，开发者使用标准C++语法和类库API进行编程。Ascend C编程类库API示意图如下所示，分为：</p><ul><li><p><strong>语言扩展层C API</strong>：开放芯片完备编程能力，支持数组分配内存，一般基于指针编程，提供与业界一致的C语言编程体验。</p></li><li><p><strong>基础API</strong>：实现对硬件能力的抽象，开放芯片的能力，保证完备性和兼容性。标注为ISASI（Instruction Set Architecture Special Interface，硬件体系结构相关的接口）类别的API，不能保证跨硬件版本兼容。</p></li><li><p><strong>高阶API</strong>：实现一些常用的计算算法，用于提高编程开发效率，通常会调用多种基础API实现。高阶API包括数学库、Matmul、Softmax等API。高阶API可以保证兼容性。</p></li><li><p><strong>Utils API（公共辅助函数）</strong>：丰富的通用工具类，涵盖标准库、平台信息获取、运行时编译及日志输出等功能，支持开发者高效实现算子开发与性能优化。</p></li></ul><img src="'+a+'" alt="架构图" width="1000px"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 Ascend C API所在头文件目录为：</p><ul><li>语言扩展层C API：<code>${INSTALL_DIR}/asc/include/c_api</code></li><li>基础API：<code>${INSTALL_DIR}/asc/include/basic_api</code></li><li>高阶API：（注意，如下目录头文件中包含的接口如果未在资料中声明，属于间接调用接口，开发者无需关注） <ul><li><code>${INSTALL_DIR}/asc/include/adv_api</code></li><li><code>${INSTALL_DIR}/asc/include/tiling</code>，</li></ul></li><li>Utils API：<code>${INSTALL_DIR}/asc/include/utils</code><code>${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</li></ul><p>使用Ascend C API依赖的库文件说明如下：</p><ul><li>语言扩展层C API：不涉及</li><li>基础API：不涉及</li><li>高阶API：因高阶API配套Host Tiling接口，需要链接libtiling_api.a。</li><li>Utils API：不涉及</li></ul></div></article></div>',1)])])}const I=e(o,[["render",c]]);export{u as __pageData,I as default};
